// ─── Step config ──────────────────────────────────────────────────────────────
const STEPS = [
  { label: "Basic Info",  short: "01", icon: "✦", hint: "Title, goal & category" },
  { label: "Story",       short: "02", icon: "✍",  hint: "Your campaign narrative" },
  { label: "Media",       short: "03", icon: "🖼", hint: "Images & video" },
