        )}
      </AnimatePresence>

      <div style={{ maxWidth: 800, margin: "0 auto", padding: "36px 20px 0", position: "relative", zIndex: 1 }}>

        {/* ─── Header ─────────────────────────────────────────────────────── */}
        <motion.div
