      <span style={{ opacity: active ? 1 : (hovered ? 0.85 : 0.6), flexShrink: 0, display: "flex" }}>
        {icon}
      </span>
      <span style={{
        fontFamily: "DM Sans, sans-serif", fontSize: 13.5,
        fontWeight: active ? 600 : 500, flex: 1,
