            ))}
          </AnimatePresence>
        </div>
      )}

      <style>{`
        @keyframes shimmer { 0%{transform:translateX(-100%)} 60%{transform:translateX(200%)} 100%{transform:translateX(200%)} }
        @keyframes svpulse { 0%,100%{opacity:.35} 50%{opacity:.85} }
      `}</style>
    </div>
  );
}

